'use client';

import React from 'react';

/** A single accordion section definition. */
export interface AccordionItem {
  /** Unique key for this section. */
  value: string;
  /** Trigger label text. */
  label: string;
  /** Content rendered when expanded. */
  content: React.ReactNode;
}

/** Props for the {@link Accordion} component. */
export interface AccordionProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Accordion sections. */
  items: AccordionItem[];
  /** Currently open section value(s). Controls single or multiple. */
  value?: string | string[];
  /** Default open section(s) (uncontrolled). */
  defaultValue?: string | string[];
  /** Called when open sections change. */
  onValueChange?: (value: string[]) => void;
  /** Allow multiple sections to be open simultaneously. */
  multiple?: boolean;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Collapsible sections with dither overlay on open items.
 * Manages expand/collapse state with optional multi-select.
 */
export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  ({ items, value, defaultValue, onValueChange, multiple = false, className, ...rest }, ref) => {
    const normalize = (v: string | string[] | undefined): string[] => {
      if (v === undefined) return [];
      return Array.isArray(v) ? v : [v];
    };

    const [internal, setInternal] = React.useState<string[]>(normalize(defaultValue));
    const openItems = value !== undefined ? normalize(value) : internal;

    const toggle = React.useCallback(
      (itemValue: string) => {
        let next: string[];
        if (openItems.includes(itemValue)) {
          next = openItems.filter((v) => v !== itemValue);
        } else {
          next = multiple ? [...openItems, itemValue] : [itemValue];
        }
        if (value === undefined) setInternal(next);
        onValueChange?.(next);
      },
      [openItems, multiple, value, onValueChange],
    );

    return (
      <div ref={ref} className={`sk-accordion${className ? ` ${className}` : ''}`} {...rest}>
        {items.map((item) => {
          const isOpen = openItems.includes(item.value);
          return (
            <div
              key={item.value}
              className="sk-accordion__item"
              data-open={isOpen ? '' : undefined}
            >
              <button
                className="sk-accordion__trigger"
                aria-expanded={isOpen}
                onClick={() => toggle(item.value)}
              >
                <span>{item.label}</span>
                <span className="sk-accordion__chevron">{isOpen ? '\u25BE' : '\u25B8'}</span>
              </button>
              {isOpen && <div className="sk-accordion__content">{item.content}</div>}
            </div>
          );
        })}
      </div>
    );
  },
);

Accordion.displayName = 'Accordion';

/**
 * skeehn — Accordion Component
 *
 * @component sk-accordion
 * @variants  default | [data-variant="pixel"] | [data-variant="retro"] | [data-variant="ascii"]
 * @states    [data-open] | [data-loading] | [data-skeleton]
 * @slots     __item | __trigger | __chevron | __content
 * @a11y      Button triggers, aria-expanded, keyboard navigation
 * @print     All panels expanded, no animations
 */

.sk-accordion { width: 100%; border: var(--sk-border); border-radius: var(--sk-radius); overflow: hidden; font-family: var(--sk-font-mono); }
.sk-accordion__item { border-bottom: var(--sk-border); position: relative; }
.sk-accordion__item:last-child { border-bottom: none; }
.sk-accordion__item::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: 0; pointer-events: none; transition: opacity var(--sk-transition-fast); }
.sk-accordion__item[data-open]::before { opacity: calc(var(--sk-dither-opacity, 0.15) * 0.3); }
.sk-accordion__trigger { display: flex; justify-content: space-between; align-items: center; width: 100%; padding: var(--sk-space-3) var(--sk-space-4); font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); font-weight: 500; color: hsl(var(--sk-foreground)); background: transparent; border: none; cursor: pointer; text-align: left; transition: background var(--sk-transition-fast); position: relative; z-index: 1; letter-spacing: 0.01em; }
.sk-accordion__trigger:hover { background: hsl(var(--sk-accent)); }
.sk-accordion__chevron { transition: transform var(--sk-transition); font-size: var(--sk-font-size-xs); color: hsl(var(--sk-muted-foreground)); }
.sk-accordion__item[data-open] .sk-accordion__chevron { transform: rotate(180deg); }
.sk-accordion__content { padding: 0 var(--sk-space-4) var(--sk-space-4); font-size: var(--sk-font-size-sm); color: hsl(var(--sk-muted-foreground)); line-height: var(--sk-line-height); position: relative; z-index: 1; }

/* Micro-interactions */
.sk-accordion__trigger:active { transform: translateY(1px); }
.sk-accordion__trigger:focus-visible { outline: 2px solid hsl(var(--sk-ring)); outline-offset: -2px; }

/* Pixel variant */
.sk-accordion[data-variant="pixel"] { border: 2px solid hsl(var(--sk-foreground)); box-shadow: 4px 4px 0 hsl(var(--sk-foreground)); }
.sk-accordion[data-variant="pixel"] .sk-accordion__item { border-bottom: 2px solid hsl(var(--sk-foreground)); }

/* Retro variant */
.sk-accordion[data-variant="retro"] { box-shadow: 0 0 8px hsl(var(--sk-foreground) / 0.06); }
.sk-accordion[data-variant="retro"] .sk-accordion__item::before { background-image: var(--sk-dither-scanlines); background-size: 100% 4px; }

/* ASCII variant */
.sk-accordion[data-variant="ascii"] { border: none; }
.sk-accordion[data-variant="ascii"] .sk-accordion__item { border-bottom: 1px dashed hsl(var(--sk-border-color)); }
.sk-accordion[data-variant="ascii"] .sk-accordion__chevron::before { content: "+"; }
.sk-accordion[data-variant="ascii"] .sk-accordion__item[data-open] .sk-accordion__chevron::before { content: "-"; }

/* Loading */
.sk-accordion[data-loading] .sk-accordion__content { position: relative; opacity: 0.5; pointer-events: none; }
.sk-accordion[data-loading] .sk-accordion__content::after {
  content: ""; position: absolute; inset: 0;
  background-image: var(--sk-dither-pattern); background-repeat: repeat;
  opacity: 0.06; animation: sk-pulse-dither 2s ease-in-out infinite; pointer-events: none;
}

/* Skeleton */
.sk-accordion[data-skeleton] .sk-accordion__trigger { color: transparent; background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%); background-size: 200% 100%; animation: sk-card-shimmer 1.8s ease-in-out infinite; pointer-events: none; }
.sk-accordion[data-skeleton] .sk-accordion__chevron { display: none; }

@media print {
  .sk-accordion { box-shadow: none; border: 1px solid hsl(var(--sk-foreground)); }
  .sk-accordion__item::before { display: none; }
  .sk-accordion__content { display: block; }
  .sk-accordion__chevron { display: none; }
  .sk-accordion[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-accordion__trigger { transition: none; }
  .sk-accordion__chevron { transition: none; }
  .sk-accordion[data-loading] .sk-accordion__content::after { animation: none; }
  .sk-accordion[data-skeleton] .sk-accordion__trigger { animation: none; background: hsl(var(--sk-muted)); }
}
